import { defineConfig } from 'vite';

// https://vitejs.dev/config/
export default defineConfig({
  test: {
    environment: 'node',
    include: ['**/*.test.ts', '**/*.test.tsx'],
  },
});

import vue from '@vitejs/plugin-vue';
import { defineConfig } from 'vitest/config';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [vue()],
  test: {
    environment: 'jsdom',
    include: ['src/**/*.ui.test.ts', 'src/**/*.ui.test.tsx'],
    setupFiles: ['./src/vitest-setup.ts'],
  },
});

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'jsdom',
    include: ['src/lib/**/*.test.ts'],
  },
});

import { defineConfig, devices } from '@playwright/test';

const port = 14983;
const baseURL = `http://localhost:${port}`;

export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: false,
  workers: 1,
  reporter: 'list',
  use: {
    ...devices['Desktop Chrome'],
    baseURL,
  },
  webServer: {
    command: `AI_SDK_DEVTOOLS_PORT=${port} pnpm tsx src/viewer/server.ts`,
    url: baseURL,
    reuseExistingServer: false,
  },
});

import { readFileSync } from 'node:fs';
import { defineConfig } from 'vitest/config';

const version = JSON.parse(
  readFileSync(new URL('./package.json', import.meta.url), 'utf-8'),
).version;

export function createVitestConfig(environment) {
  return defineConfig({
    define: {
      __PACKAGE_VERSION__: JSON.stringify(version),
    },
    test: {
      environment,
      include: ['**/*.test.ts{,x}'],
      exclude: [
        '**/*.ui.test.ts{,x}',
        '**/*.e2e.test.ts{,x}',
        '**/node_modules/**',
      ],
      typecheck: {
        enabled: true,
      },
    },
  });
}

import { devices, type PlaywrightTestConfig } from '@playwright/test';
const PORT = process.env.PORT || 3000;
const baseURL = `http://localhost:${PORT}`;

/**
 * See https://playwright.dev/docs/test-configuration.
 */
const config: PlaywrightTestConfig = {
  testDir: './tests/e2e/spec',
  snapshotPathTemplate: './tests/e2e/__snapshots__/{testFilePath}/{arg}{ext}',
  timeout: 20_000,
  expect: {
    timeout: 10_000,
  },
  fullyParallel: false,
  workers: 3,
  retries: 2,
  reporter: process.env.CI
    ? [['github'], ['json', { outputFile: 'test-results.json' }]]
    : 'list',
  projects: [
    {
      name: 'chromium',
      use: devices['Desktop Chrome'],
    },
  ],
  use: {
    baseURL,
    trace: 'retain-on-failure',
    userAgent: 'playwright-test bot',
  },
  webServer: {
    cwd: './tests/e2e/next-server',
    command: 'pnpm run dev',
    url: baseURL,
    timeout: 120 * 1000,
    reuseExistingServer: false,
  },
};

export default config;

import react from '@vitejs/plugin-react';
import { defineConfig } from 'vitest/config';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  test: {
    environment: 'jsdom',
    include: ['src/**/*.test.ts', 'src/**/*.test.tsx'],
    setupFiles: ['./src/vitest-setup.ts'],
  },
});

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'node',
    exclude: ['dist/**', 'node_modules/**'],
    // Codemod tests do CPU-heavy TypeScript syntax validation and can exceed
    // Vitest's default 5s timeout on saturated CI runners, especially in the
    // Node 24 matrix where the root test job runs many packages concurrently.
    // See https://github.com/vercel/ai/issues/15255.
    maxWorkers: process.env.CI ? 2 : undefined,
    testTimeout: process.env.CI ? 30_000 : 5_000,
  },
});

